 @Test void unfinishedSourceCanBeCancelledAndRebuiltButCannotReviveOldApprovals(){var input=revenue(1,"100.00","AR");call(()->service.importRevenue(input));call(()->service.cancelDraft("REVENUE",input.requestId(),confirm(0)));as(reviewer,"finance.review");assertThatThrownBy(()->call(()->service.confirmRevenue(input.requestId(),confirm(1)))).isInstanceOf(RuntimeException.class);as(owner,"*");call(()->service.importRevenue(revenue(2,"100.00","AR")));var payroll=payroll(null);call(()->service.createPayroll(payroll));call(()->service.cancelDraft("PAYROLL",payroll.requestId(),confirm(0)));call(()->service.createPayroll(payroll(null)));var transaction=new Intercompany(UUID.randomUUID(),hotel,counterHotel,"2026-10","SERVICE",new BigDecimal("100"),"真实依据",List.of(new Basis("实际",BigDecimal.ONE,"对账单")),reviewer,counterReviewer);call(()->service.createIntercompany(transaction));as(reviewer,"finance.review");call(()->service.confirmIntercompany(transaction.requestId(),confirm(0)));as(owner,"*");call(()->service.cancelDraft("INTERCOMPANY",transaction.requestId(),confirm(1)));as(counterReviewer,"finance.review");assertThatThrownBy(()->call(()->service.confirmIntercompany(transaction.requestId(),confirm(2)))).hasMessageContaining("不可恢复旧节点");assertThat(jdbc.queryForObject("select count(*) from fa_source_event where source_id=?",Integer.class,transaction.requestId())).isZero();}
 @Test void realNormalizedFilePreviewImportAndOriginalDownloadKeepExactBytes()throws Exception{var mapper=new ObjectMapper().findAndRegisterModules().disable(com.fasterxml.jackson.databind.SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);try(var factory=Validation.buildDefaultValidatorFactory()){var evidence=new FinanceBusinessEvidenceService(Files.createTempDirectory("finance-business-original-").toString(),service,new AccessPolicy(),new AttachmentMalwareScanner("","",1,true,false),mapper,factory.getValidator());var input=revenue(1,"100.00","AR");byte[] bytes=mapper.writeValueAsBytes(input);var file=new MockMultipartFile("file","PMS实际规范日结.json","application/json",bytes);call(()->evidence.importRevenueFile(file,true));assertThat(jdbc.queryForObject("select count(*) from fb_revenue_batch where id=?",Integer.class,input.requestId())).isZero();call(()->evidence.importRevenueFile(file,false));call(()->evidence.importRevenueFile(file,false));UUID attachment=jdbc.queryForObject("select id from fb_attachment where resource_id=?",UUID.class,input.requestId());assertThat(call(()->{try{return evidence.download("REVENUE",input.requestId(),attachment).resource().getContentAsByteArray();}catch(Exception e){throw new RuntimeException(e);}})).isEqualTo(bytes);assertThat(jdbc.queryForObject("select status from fb_revenue_batch where id=?",String.class,input.requestId())).isEqualTo("REVIEW");}}
 @Test void revenueCashAndRevisionsCarryForwardSettlementAndCommission(){UUID first=confirmedRevenue(revenue(1,"100.00","AR"));as(cashier,"finance.pay");var payment=new RevenueMovement(UUID.randomUUID(),"RECEIPT",new BigDecimal("80"),DAY,"实际到账流水","净额含佣金10");call(()->service.moveRevenue(first,payment));call(()->service.moveRevenue(first,payment));assertThatThrownBy(()->call(()->service.moveRevenue(first,new RevenueMovement(UUID.randomUUID(),"RECEIPT",new BigDecimal("11"),DAY,"流水2","超额")))).hasMessageContaining("超过结算净额");as(owner,"*");UUID second=confirmedRevenue(revenue(2,"110.00","AR"));as(cashier,"finance.pay");call(()->service.moveRevenue(second,new RevenueMovement(UUID.randomUUID(),"RECEIPT",new BigDecimal("20"),DAY,"补收流水","重结补收")));as(owner,"finance.read");var account=items(call(()->service.revenueAccounts())).stream().filter(r->second.equals(r.get("id"))).findFirst().orElseThrow();assertThat(account).containsEntry("receivedAmount","100.00").containsEntry("outstandingAmount","0.00");}
