 @Test void outputRequestsSplitMergeRedAndDuplicateRevisionReservations(){UUID entry=confirmedRevenue(revenue(1,"100.00","INCOME"));as(owner,"finance.tax");var request=new OutputRequest(UUID.randomUUID(),hotel,"真实客户","00001234",List.of(new InvoiceAllocation(entry,new BigDecimal("60"))));call(()->service.createOutput(request));call(()->service.createOutput(request));UUID attachment=original("OUTPUT",request.requestId());var invoice=new InvoiceResult(UUID.randomUUID(),0,"000001","00000000000000001234",new BigDecimal("57"),new BigDecimal("3"),DAY,null,attachment,"真实外部开票流水");call(()->service.registerInvoice(request.requestId(),invoice));call(()->service.registerInvoice(request.requestId(),invoice));assertThat(jdbc.queryForObject("select invoice_number from fb_output_invoice where id=?",String.class,invoice.requestId())).isEqualTo("00000000000000001234");assertThatThrownBy(()->call(()->service.executeInvoice(request.requestId()))).hasMessageContaining("未配置");
  call(()->service.registerInvoice(request.requestId(),new InvoiceResult(UUID.randomUUID(),1,"000002","00000000000000001235",new BigDecimal("19"),BigDecimal.ONE,DAY,invoice.requestId(),attachment,"真实红字流水")));assertThatThrownBy(()->call(()->service.registerInvoice(request.requestId(),new InvoiceResult(UUID.randomUUID(),2,"000003","00000000000000001236",new BigDecimal("40"),new BigDecimal("3"),DAY,invoice.requestId(),attachment,"超额红字")))).hasMessageContaining("不得超过");
  as(owner,"*");UUID revised=confirmedRevenue(revenue(2,"100.00","INCOME"));as(owner,"finance.tax");assertThatThrownBy(()->call(()->service.createOutput(new OutputRequest(UUID.randomUUID(),hotel,"真实客户","00001234",List.of(new InvoiceAllocation(revised,new BigDecimal("41"))))))).hasMessageContaining("历次重结");}
 @Test void employeePayrollComponentsSupplementAndPartialPayAreIndependentAndSensitive(){var input=payroll(null);call(()->service.createPayroll(input));original("PAYROLL",input.requestId());as(owner,"finance.payroll","finance.review");assertThatThrownBy(()->call(()->service.confirmPayroll(input.requestId(),confirm(0)))).hasMessageContaining("授权办理人");as(reviewer,"finance.payroll","finance.review");call(()->service.confirmPayroll(input.requestId(),confirm(0)));var d=call(()->service.payrollDetail(input.requestId()));assertThat(d).containsEntry("grossAmount","100.30").containsEntry("deductionAmount","10.10").containsEntry("netAmount","90.20").containsEntry("employerAmount","20.05");UUID line=(UUID)itemsFrom(d,"lines").getFirst().get("id");as(cashier,"finance.payroll","finance.pay");var payment=new PayrollPayment(UUID.randomUUID(),line,new BigDecimal("40.10"),DAY,"工资真实流水01");call(()->service.payPayroll(input.requestId(),payment));call(()->service.payPayroll(input.requestId(),payment));assertThatThrownBy(()->call(()->service.payPayroll(input.requestId(),new PayrollPayment(UUID.randomUUID(),line,new BigDecimal("50.11"),DAY,"超付")))).hasMessageContaining("实发净额");call(()->service.payPayroll(input.requestId(),new PayrollPayment(UUID.randomUUID(),line,new BigDecimal("50.10"),DAY,"工资真实流水02")));as(owner,"finance.read");assertThatThrownBy(()->call(()->service.payrollDetail(input.requestId()))).isInstanceOf(AccessDeniedException.class);as(owner,"*");call(()->service.createPayroll(payroll(input.requestId())));}
 @Test void bilateralConfirmationFreezesBasisAndCreatesMirrorsOnlyAfterBothSides(){var input=new Intercompany(UUID.randomUUID(),hotel,counterHotel,"2026-10","ALLOCATION",new BigDecimal("0.05"),"真实面积报表",List.of(new Basis("A",BigDecimal.ONE,"面积1"),new Basis("B",BigDecimal.ONE,"面积2")),reviewer,counterReviewer);call(()->service.createIntercompany(input));as(reviewer,"finance.review");call(()->service.confirmIntercompany(input.requestId(),confirm(0)));assertThat(jdbc.queryForObject("select count(*) from fa_source_event where source_id=?",Integer.class,input.requestId())).isZero();as(counterReviewer,Set.of(counterHotel),"finance.review");call(()->service.confirmIntercompany(input.requestId(),confirm(1)));assertThat(jdbc.queryForObject("select count(*) from fa_source_event where source_id=?",Integer.class,input.requestId())).isEqualTo(2);var rows=jdbc.queryForList("select metadata->>'side' side,amount from fa_source_event where source_id=?",input.requestId());assertThat(rows).extracting(r->r.get("side")).containsExactlyInAnyOrder("ORIGIN","COUNTERPARTY");assertThatThrownBy(()->jdbc.update("update fb_intercompany set amount=1 where id=?",input.requestId())).hasMessageContaining("immutable");}
 @Test void publishedConsolidationMissingBooksIsIncompleteNotFakeFinal(){var scope=new ConsolidationScope(UUID.randomUUID(),"真实范围"+UUID.randomUUID(),1,List.of(hotel,counterHotel),List.of(new EliminationRule("INTERNAL_REVENUE","INTERNAL_COST","SERVICE")));call(()->service.createScope(scope));assertThatThrownBy(()->call(()->service.publishScope(scope.requestId(),confirm(1)))).hasMessageContaining("授权办理人");as(reviewer,"finance.configure","finance.accounting.read","finance.payroll");call(()->service.publishScope(scope.requestId(),confirm(1)));var result=call(()->service.worksheet(new Worksheet(UUID.randomUUID(),scope.requestId(),"2026-10")));assertThat(((Map<?,?>)result.get("snapshot")).get("status")).isEqualTo("INCOMPLETE_WORKSHEET");}
 @Test void taxPolicyNoHardcodedRatesIndependentPublishAndRealFilingPaymentReceipts(){UUID policy=policy();as(owner,"finance.tax");var input=new TaxReturn(UUID.randomUUID(),hotel,"2026-10",policy,new BigDecimal("20"),"经财务确认实际申报应缴；票账差异另附说明");call(()->service.createTaxReturn(input));UUID attachment=original("TAX",input.requestId());assertThatThrownBy(()->call(()->service.recordTaxReceipt(input.requestId(),new TaxReceipt(UUID.randomUUID(),"PAYMENT","未申报完税",new BigDecimal("1"),attachment,DAY)))).hasMessageContaining("先归档");call(()->service.recordTaxReceipt(input.requestId(),new TaxReceipt(UUID.randomUUID(),"FILING","真实申报流水",new BigDecimal("20"),attachment,DAY)));call(()->service.recordTaxReceipt(input.requestId(),new TaxReceipt(UUID.randomUUID(),"PAYMENT","真实完税流水",new BigDecimal("20"),attachment,DAY)));assertThatThrownBy(()->call(()->service.recordTaxReceipt(input.requestId(),new TaxReceipt(UUID.randomUUID(),"PAYMENT","超缴",BigDecimal.ONE,attachment,DAY)))).hasMessageContaining("超过");as(owner,"finance.read");assertThatThrownBy(()->call(()->service.taxReturns())).isInstanceOf(AccessDeniedException.class);}
