 @Test void revenueCashErrorCorrectionIsIndependentAndCannotInvadeConsumedFunds(){UUID entry=confirmedRevenue(revenue(1,"100.00","STORED_VALUE"));as(cashier,"finance.pay");var receipt=new RevenueMovement(UUID.randomUUID(),"RECEIPT",new BigDecimal("90"),DAY,"原充值登记","真实依据");call(()->service.moveRevenue(entry,receipt));UUID target=redemptionTarget();call(()->service.moveRevenue(entry,new RevenueMovement(UUID.randomUUID(),"REDEEM",new BigDecimal("80"),DAY,"已消费","已实际消费",target)));as(cashier,"finance.review");assertThatThrownBy(()->call(()->service.correctCash(correction("REVENUE",receipt.requestId(),"10",List.of())))).hasMessageContaining("独立授权");as(reviewer,"finance.review");assertThatThrownBy(()->call(()->service.correctCash(correction("REVENUE",receipt.requestId(),"11",List.of())))).hasMessageContaining("不能盲目冲回");var correction=correction("REVENUE",receipt.requestId(),"10",List.of());call(()->service.correctCash(correction));call(()->service.correctCash(correction));assertThat(jdbc.queryForObject("select amount from fb_revenue_movement where id=?",BigDecimal.class,receipt.requestId())).isEqualByComparingTo("90");assertThat(jdbc.queryForObject("select fb_cash_effective_amount(?,?,?,90,?)",BigDecimal.class,T,"REVENUE",receipt.requestId(),DAY)).isEqualByComparingTo("80");assertThat(jdbc.queryForObject("select fb_cash_effective_amount(?,?,?,90,?)",BigDecimal.class,T,"REVENUE",receipt.requestId(),DAY.minusDays(1))).isEqualByComparingTo("90");}
 @Test void matchedRevenueCorrectionNeedsImmutableBankMatchReverseAndReleasesOnlyItsOwnBankAmount(){
  UUID entry=confirmedRevenue(revenue(1,"100.00","AR"));as(cashier,"finance.pay");
  var receipt=new RevenueMovement(UUID.randomUUID(),"RECEIPT",new BigDecimal("80"),DAY,"原收款事实","凭据");call(()->service.moveRevenue(entry,receipt));
  UUID bank=bankTransaction("IN","80");call(()->service.matchBank(new BankMatch(UUID.randomUUID(),bank,List.of(new CashAllocation("REVENUE",receipt.requestId(),new BigDecimal("80"))),"实际核对")));
  UUID match=jdbc.queryForObject("select id from fb_bank_match where transaction_id=?",UUID.class,bank);
  LocalDate matchedOn=jdbc.queryForObject("select (created_at at time zone 'Asia/Shanghai')::date from fb_bank_match where id=?",LocalDate.class,match);
  // A later real reconciliation must not be backdated to the fixed business day.
  LocalDate asOf=matchedOn.isAfter(DAY)?matchedOn:DAY;
  as(reviewer,"finance.review");assertThatThrownBy(()->call(()->service.correctCash(correction("REVENUE",receipt.requestId(),"20",List.of())))).hasMessageContaining("明确匹配逆向");
  call(()->service.correctCash(correction("REVENUE",receipt.requestId(),"20",List.of(new MatchUndo(match,new BigDecimal("20"))))));
  assertThat(jdbc.queryForObject("select amount from fb_bank_match where id=?",BigDecimal.class,match)).isEqualByComparingTo("80");
  assertThat(jdbc.queryForObject("select fb_bank_allocated_amount(?,?,?)",BigDecimal.class,T,bank,asOf)).isEqualByComparingTo("60");
  assertThat(jdbc.queryForObject("select fb_bank_allocated_amount(?,?,?)",BigDecimal.class,T,bank,matchedOn.minusDays(1))).isZero();
  assertThatThrownBy(()->jdbc.update("delete from fb_bank_match_reversal where match_id=?",match)).hasMessageContaining("append-only");
 }
 @Test void payrollErrorCorrectionRestoresOnlyNetUnpaidAmountAndRetainsOriginalWageFact(){as(owner,"*");var payroll=payroll(null);call(()->service.createPayroll(payroll));original("PAYROLL",payroll.requestId());as(reviewer,"finance.review","finance.payroll");call(()->service.confirmPayroll(payroll.requestId(),confirm(0)));UUID line=jdbc.queryForObject("select id from fb_payroll_line where batch_id=?",UUID.class,payroll.requestId());as(cashier,"finance.pay","finance.payroll");var payment=new PayrollPayment(UUID.randomUUID(),line,new BigDecimal("80"),DAY,"原工资付款");call(()->service.payPayroll(payroll.requestId(),payment));as(reviewer,"finance.review");assertThatThrownBy(()->call(()->service.correctCash(correction("PAYROLL",payment.requestId(),"20",List.of())))).isInstanceOf(AccessDeniedException.class);as(reviewer,"finance.review","finance.payroll");call(()->service.correctCash(correction("PAYROLL",payment.requestId(),"20",List.of())));assertThatThrownBy(()->call(()->service.correctCash(correction("PAYROLL",payment.requestId(),"61",List.of())))).hasMessageContaining("净有效金额");as(cashier,"finance.pay","finance.payroll");call(()->service.payPayroll(payroll.requestId(),new PayrollPayment(UUID.randomUUID(),line,new BigDecimal("30.20"),DAY,"更正后实际补付")));assertThatThrownBy(()->call(()->service.payPayroll(payroll.requestId(),new PayrollPayment(UUID.randomUUID(),line,new BigDecimal("0.01"),DAY,"再次超额")))).hasMessageContaining("实发净额");}
 @Test void intercompanyCashErrorCorrectionKeepsBothSidesIndependent(){as(owner,"*");var transaction=new Intercompany(UUID.randomUUID(),hotel,counterHotel,"2026-10","SERVICE",new BigDecimal("100"),"实际服务协议",List.of(new Basis("实际服务",BigDecimal.ONE,"对账单")),reviewer,counterReviewer);call(()->service.createIntercompany(transaction));as(reviewer,"finance.review");call(()->service.confirmIntercompany(transaction.requestId(),confirm(0)));as(counterReviewer,"finance.review");call(()->service.confirmIntercompany(transaction.requestId(),confirm(1)));as(cashier,"finance.pay");var receipt=new IntercompanySettlement(UUID.randomUUID(),"ORIGIN",new BigDecimal("80"),DAY,"本方收款误登记");call(()->service.settleIntercompany(transaction.requestId(),receipt));as(reviewer,"finance.review");call(()->service.correctCash(correction("INTERCOMPANY",receipt.requestId(),"20",List.of())));var detail=call(()->service.intercompanyDetail(transaction.requestId()));assertThat(detail).containsEntry("originSettled","60.00").containsEntry("counterpartySettled","0");assertThatThrownBy(()->call(()->service.correctCash(correction("INTERCOMPANY",receipt.requestId(),"61",List.of())))).hasMessageContaining("净有效金额");}
 @Test void openingCashErrorCorrectionRequiresOpenPeriodAndDoesNotRewriteHistoricalOpening(){as(owner,"*");UUID book=book(hotel),batch=UUID.randomUUID(),subledger=UUID.randomUUID();jdbc.update("insert into fm_batch(id,tenant_id,book_id,kind,original_name,source_reference,file_sha256,mapping,status,created_by) values(?,?,?,'OPEN_ITEM','实际金蝶未清.json','已核对来源',?,'{}','ACTIVE',?)",batch,T,book,"0".repeat(64),owner);jdbc.update("insert into fm_subledger(id,tenant_id,book_id,batch_id,kind,source_key,account_code,name,direction,business_date,original_amount,remaining_amount,status) values(?,?,?,?,'OPEN_ITEM',?,'AR','真实期初客户应收','DEBIT',?,100,100,'ACTIVE')",subledger,T,book,batch,subledger.toString(),DAY.withDayOfMonth(1));as(cashier,"finance.pay");var clear=new OpeningClear(UUID.randomUUID(),new BigDecimal("80"),DAY,"期初实收误登记");call(()->service.clearOpening(subledger,clear));jdbc.update("insert into fa_period(tenant_id,book_id,month,status) values(?,?,?,'CLOSED') on conflict(tenant_id,book_id,month) do update set status='CLOSED'",T,book,DAY.withDayOfMonth(1));as(reviewer,"finance.review");assertThatThrownBy(()->call(()->service.correctCash(correction("OPENING",clear.requestId(),"30",List.of())))).hasMessageContaining("已锁定");jdbc.update("update fa_period set status='OPEN' where book_id=?",book);call(()->service.correctCash(correction("OPENING",clear.requestId(),"30",List.of())));assertThat(jdbc.queryForObject("select remaining_amount from fm_subledger where id=?",BigDecimal.class,subledger)).isEqualByComparingTo("100");assertThat(items(call(()->service.openingItems())).getFirst()).containsEntry("clearedAmount","50.00").containsEntry("outstandingAmount","50.00");assertThatThrownBy(()->call(()->service.correctCash(correction("OPENING",clear.requestId(),"51",List.of())))).hasMessageContaining("净有效金额");}
 @Test void sourceSpecificBankMatchingIsManyToManyAtomicAndRespectsOtherDomainAllocations(){UUID entry=confirmedRevenue(revenue(1,"100.00","AR"));as(cashier,"finance.pay");var receipt=new RevenueMovement(UUID.randomUUID(),"RECEIPT",new BigDecimal("80"),DAY,"实际渠道收款","原始依据");call(()->service.moveRevenue(entry,receipt));UUID bank=UUID.randomUUID(),transaction=UUID.randomUUID();jdbc.update("insert into fo_bank_account(id,tenant_id,hotel_id,name,account_number,bank_name,opening_date,opening_balance,created_by) values(?,?,?,'真实银行账户',?,'测试银行',?,0,?)",bank,T,hotel,bank.toString(),DAY,cashier);jdbc.update("insert into fo_bank_transaction(id,tenant_id,bank_account_id,batch_id,external_id,occurred_on,direction,amount,source_hash,created_by) values(?,?,?,?,?,?,'IN',80,?,?)",transaction,T,bank,UUID.randomUUID(),transaction.toString(),DAY,"0".repeat(64),cashier);var first=new BankMatch(UUID.randomUUID(),transaction,List.of(new CashAllocation("REVENUE",receipt.requestId(),new BigDecimal("30"))),"第一笔实际分配");call(()->service.matchBank(first));call(()->service.matchBank(first));call(()->service.matchBank(new BankMatch(UUID.randomUUID(),transaction,List.of(new CashAllocation("REVENUE",receipt.requestId(),new BigDecimal("50"))),"余款实际分配")));assertThat(jdbc.queryForObject("select sum(amount) from fb_bank_match where transaction_id=?",BigDecimal.class,transaction)).isEqualByComparingTo("80");assertThatThrownBy(()->call(()->service.matchBank(new BankMatch(UUID.randomUUID(),transaction,List.of(new CashAllocation("REVENUE",receipt.requestId(),new BigDecimal("0.01"))),"超额")))).hasMessageContaining("剩余");assertThat(items(call(()->service.cashFacts())).getFirst()).containsEntry("reconciliationStatus","MATCHED");}
 @Test void actualInputDeductionsTransfersAndTaxReturnUseSamePolicyVersionAndExactSources(){UUID policy=policy(),claim=UUID.randomUUID(),invoice=UUID.randomUUID(),attachment=UUID.randomUUID();jdbc.update("insert into finance_claim(id,tenant_id,applicant_id,assignment_id,hotel_id,company_id,applicant_name,hotel_name,company_name,company_tax_number,business_date,status,manager_account_id,finance_account_id,leader_account_id,config_version) values(?,?,?,?,?,?,'测试员工','测试店','测试法人','真实税号',?,'APPROVED',?,?,?,1)",claim,T,employee,assignment,hotel,company,DAY,reviewer,counterReviewer,cashier);jdbc.update("insert into finance_attachment(id,tenant_id,claim_id,kind,original_name,media_type,size_bytes,sha256,object_key,scan_status) values(?,?,?,'INVOICE','发票.pdf','application/pdf',100,?,?,'CLEAN')",attachment,T,claim,"0".repeat(64),attachment.toString());jdbc.update("insert into finance_invoice(id,tenant_id,claim_id,attachment_id,invoice_number,invoice_key,amount,buyer_tax_number,confirmed) values(?,?,?,?,?,?,100,'真实税号',true)",invoice,T,claim,attachment,"00001",invoice.toString());as(owner,"finance.tax");var deduction=new InputTax(UUID.randomUUID(),hotel,invoice,"2026-10","经营用途",new BigDecimal("5"),new BigDecimal("5"),BigDecimal.ZERO,policy,"财务核对原票及实际用途");call(()->service.recordInputTax(deduction));call(()->service.recordInputTax(deduction));call(()->service.recordInputTax(new InputTax(UUID.randomUUID(),hotel,invoice,"2026-10","用途改变转出",new BigDecimal("5"),BigDecimal.ZERO,new BigDecimal("2"),policy,"实际用途改变依据")));assertThatThrownBy(()->call(()->service.recordInputTax(new InputTax(UUID.randomUUID(),hotel,invoice,"2026-10","转出",new BigDecimal("5"),BigDecimal.ZERO,new BigDecimal("4"),policy,"过量转出")))).hasMessageContaining("累计转出");var result=call(()->service.createTaxReturn(new TaxReturn(UUID.randomUUID(),hotel,"2026-10",policy,null,null)));var snapshot=(Map<?,?>)result.get("snapshot");var sources=(Map<?,?>)snapshot.get("sources");assertThat(sources.get("INPUT_CLAIMED")).isEqualTo("5.00");assertThat(sources.get("INPUT_TRANSFER_OUT")).isEqualTo("2.00");}
 @Test void postedBilateralProfitAndBalancePairsAreBothEliminatedAndNoUnrelatedLinesAreUsed(){as(owner,"*");UUID originBook=book(hotel),counterBook=book(counterHotel);acc(originBook,"AR","ASSET","INTERNAL_AR");acc(originBook,"REV","REVENUE","INTERNAL_REVENUE");acc(counterBook,"COST","EXPENSE","INTERNAL_COST");acc(counterBook,"AP","LIABILITY","INTERNAL_AP");call(()->accounting.saveRule(new FinanceAccountingModels.Rule(originBook,"FB_INTERCOMPANY","SERVICE_ORIGIN","AR","REV",null,true,-1)));call(()->accounting.saveRule(new FinanceAccountingModels.Rule(counterBook,"FB_INTERCOMPANY","SERVICE_COUNTERPARTY","COST","AP",null,true,-1)));var transaction=new Intercompany(UUID.randomUUID(),hotel,counterHotel,"2026-10","SERVICE",new BigDecimal("100"),"真实服务协议",List.of(new Basis("服务",BigDecimal.ONE,"双方确认单")),reviewer,counterReviewer);call(()->service.createIntercompany(transaction));as(reviewer,"finance.review");call(()->service.confirmIntercompany(transaction.requestId(),confirm(0)));as(counterReviewer,"finance.review");call(()->service.confirmIntercompany(transaction.requestId(),confirm(1)));as(owner,"*");for(UUID source:jdbc.queryForList("select id from fa_source_event where source_id=?",UUID.class,transaction.requestId()))call(()->accounting.retrySource(source));var vouchers=jdbc.queryForList("select voucher_id from fa_source_event where source_id=?",UUID.class,transaction.requestId());assertThat(vouchers).hasSize(2).doesNotContainNull();as(reviewer,"*");for(UUID voucher:vouchers){call(()->accounting.review(voucher,0));call(()->accounting.post(voucher,1));}jdbc.update("update fa_period set status='CLOSED' where book_id in (?,?)",originBook,counterBook);as(owner,"*");var scope=new ConsolidationScope(UUID.randomUUID(),"双边真实抵销"+UUID.randomUUID(),1,List.of(hotel,counterHotel),List.of(new EliminationRule("INTERNAL_REVENUE","INTERNAL_COST","SERVICE"),new EliminationRule("INTERNAL_AP","INTERNAL_AR","SERVICE")));call(()->service.createScope(scope));as(reviewer,"*");call(()->service.publishScope(scope.requestId(),confirm(1)));var worksheet=call(()->service.worksheet(new Worksheet(UUID.randomUUID(),scope.requestId(),"2026-10")));var snapshot=(Map<?,?>)worksheet.get("snapshot");assertThat(snapshot.get("status")).isEqualTo("FINAL_WORKSHEET");assertThat((Map<?,?>)snapshot.get("adjustedLines")).allSatisfy((key,value)->assertThat(new BigDecimal(value.toString())).isEqualByComparingTo("0"));}
