 @Test void sourceReviewNotificationsAreActualFrozenRecipientsAndIdempotentWithoutSensitiveDetailsOrPayment(){var revenue=revenue(1,"100.00","AR");call(()->service.importRevenue(revenue));call(()->service.importRevenue(revenue));var wages=payroll(null);call(()->service.createPayroll(wages));call(()->service.createPayroll(wages));var internal=new Intercompany(UUID.randomUUID(),hotel,counterHotel,"2026-10","SERVICE",new BigDecimal("100"),"真实内部协议",List.of(new Basis("实际服务",BigDecimal.ONE,"双方原始依据")),reviewer,counterReviewer);call(()->service.createIntercompany(internal));call(()->service.createIntercompany(internal));assertThat(jdbc.queryForObject("select count(*) from notification where source_type='FINANCE_REVENUE' and source_id=? and recipient_account_id=? and notification_type='FINANCE_REVIEW_PENDING'",Integer.class,revenue.requestId(),reviewer)).isOne();assertThat(jdbc.queryForObject("select count(*) from notification where source_type='FINANCE_PAYROLL' and source_id=? and recipient_account_id=?",Integer.class,wages.requestId(),reviewer)).isOne();assertThat(jdbc.queryForList("select recipient_account_id from notification where source_type='FINANCE_INTERCOMPANY' and source_id=?",UUID.class,internal.requestId())).containsExactlyInAnyOrder(reviewer,counterReviewer);assertThat(jdbc.queryForObject("select content from notification where source_type='FINANCE_PAYROLL' and source_id=?",String.class,wages.requestId())).doesNotContain("100.30","BASIC",employee.toString());assertThat(jdbc.queryForObject("select count(*) from fb_payroll_payment y join fb_payroll_line l on l.id=y.line_id where l.batch_id=?",Integer.class,wages.requestId())).isZero();}
